-- =====================================================================
-- DEFINITIVO — CONSUMO consolidado (25/07): baseline único e determinístico.
-- Zera meep_consumo_bar e regrava SOMENTE os 15 bares consolidados
-- (465 H / 467 A). Corrige a duplicação causada por variantes de nome
-- em seeds anteriores (ex.: "Nucleos"/"Núcleos", "Vila"/"Villa",
-- "Choperia"/"Chopperia"). Idempotente: reexecutar dá o mesmo estado.
-- bar_id é resolvido por nome (case/acento-insensível) quando o bar existir.
-- =====================================================================

-- 1) Zera a base de consumo (reconstruída integralmente abaixo).
DELETE FROM public.meep_consumo_bar;

-- 2) Regrava o consolidado (fonte: docs/consumo-25-07-consolidado.csv).
ON CONFLICT (bar_nome,data,marca) DO UPDATE SET barris = EXCLUDED.barris, bar_id = EXCLUDED.bar_id;
